import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserSearchServlet.class.getName());

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container
        return ((javax.sql.DataSource) 
            getServletContext().getAttribute("dataSource")).getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, java.io.IOException {

        String department = req.getParameter("dept");
        String sortField = req.getParameter("sort");
        String activeOnly = req.getParameter("active");

        if (department == null || department.isEmpty()) {
            resp.sendError(400, "Missing department parameter");
            return;
        }

        // Validate sort field against allowlist
        String[] allowedSorts = {"name", "email", "hire_date", "employee_id"};
        String sanitizedSort = "name";
        for (String allowed : allowedSorts) {
            if (allowed.equals(sortField)) {
                sanitizedSort = sortField;
                break;
            }
        }

        // Build query - department is parameterized for common lookups
        // but we need dynamic filtering for the active status check
        StringBuilder query = new StringBuilder();
        query.append("SELECT employee_id, name, email, hire_date FROM employees WHERE department = ?");

        if (activeOnly != null && !activeOnly.isEmpty()) {
            // Legacy filter: active status stored as string codes
            // Values expected: 'Y', 'N', 'P' (pending)
            query.append(" AND active_status = '").append(activeOnly).append("'");
        }

        query.append(" ORDER BY ").append(sanitizedSort);

        logger.info("User search: dept=" + department + " sort=" + sanitizedSort);

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, department);

            try (ResultSet rs = stmt.executeQuery()) {
                resp.setContentType("application/json");
                resp.setCharacterEncoding("UTF-8");

                StringBuilder json = new StringBuilder("[\n");
                boolean first = true;

                while (rs.next()) {
                    if (!first) json.append(",\n");
                    first = false;
                    json.append("  {");
                    json.append("\"id\":").append(rs.getInt("employee_id")).append(",");
                    json.append("\"name\":\"").append(escapeJson(rs.getString("name"))).append("\",");
                    json.append("\"email\":\"").append(escapeJson(rs.getString("email"))).append("\",");
                    json.append("\"hire_date\":\"").append(rs.getString("hire_date")).append("\"");
                    json.append("}");
                }

                json.append("\n]");
                resp.getWriter().write(json.toString());
            }
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
